// Not in a public ESP-IDF header: runs a function inside the OpenThread task.
extern "C" esp_err_t esp_openthread_task_queue_post(void (*task)(void *), void *arg);

static const char *TAG = "mesp_thread";

// OpenThread is only initialized once the radio answers: before that its lock and instance must
// not be touched.
enum RadioState { RADIO_WAITING, RADIO_STARTING, RADIO_READY };
static std::atomic<int> s_radio{RADIO_WAITING};
static std::atomic<bool> s_ip_ready{false};
static std::atomic<bool> s_br_started{false};

bool mesp_thread_ready()
{
    return s_radio.load() == RADIO_READY;
}

static uint16_t hdlc_fcs(const uint8_t *data, size_t len)
{
    uint16_t fcs = 0xffff;
    while (len--) {
        fcs ^= *data++;
        for (int i = 0; i < 8; i++) {
            fcs = (fcs & 1) ? (fcs >> 1) ^ 0x8408 : fcs >> 1;
        }
    }
    return fcs ^ 0xffff;
}

/** Send one Spinel frame (HDLC framed) to the radio. */
static void spinel_send(const uint8_t *payload, size_t len)
{
    const uint16_t fcs = hdlc_fcs(payload, len);
    uint8_t frame[2 + 2 * (16 + 2)];
    size_t n = 0;
    auto put = [&](uint8_t b) {
        if (b == 0x7e || b == 0x7d || b == 0x11 || b == 0x13 || b == 0xf8) {
            frame[n++] = 0x7d;
            frame[n++] = b ^ 0x20;
        } else {
            frame[n++] = b;
        }
    };
    frame[n++] = 0x7e;
    for (size_t i = 0; i < len && i < 16; i++) put(payload[i]);
    put(fcs & 0xff);
    put(fcs >> 8);
    frame[n++] = 0x7e;
    uart_write_bytes(UART_NUM_1, frame, n);
}

/** True if `rx` holds an HDLC frame with a valid FCS that answers `get protocol version`. */
static bool is_version_reply(const uint8_t *rx, int n)
{
    uint8_t frame[32];
    size_t len = 0;
    bool escaped = false;
    for (int i = 0; i < n; i++) {
        uint8_t b = rx[i];
        if (b == 0x7e) {
            // header with TID 1, PROP_VALUE_IS, PROTOCOL_VERSION, ..., FCS (2 bytes)
            if (len >= 5 && hdlc_fcs(frame, len - 2) == (frame[len - 2] | frame[len - 1] << 8) &&
                frame[0] == 0x81 && frame[1] == 0x06 && frame[2] == 0x01) {
                return true;
            }
            len = 0;
            escaped = false;
        } else if (b == 0x7d) {
            escaped = true;
        } else if (len < sizeof(frame)) {
            frame[len++] = escaped ? b ^ 0x20 : b;
            escaped = false;
        }
    }
    return false;
}

/** Send a Spinel "get protocol version" request and check that the radio answers it. */
static bool rcp_answers()
{
    const uint8_t payload[] = {0x81 /* header, TID 1 */, 0x02 /* PROP_VALUE_GET */, 0x01 /* PROTOCOL_VERSION */};
    uart_flush_input(UART_NUM_1);
    spinel_send(payload, sizeof(payload));
    // Noise, or the boot messages of a radio that keeps restarting, must not count as an answer.
    uint8_t rx[64];
    int n = uart_read_bytes(UART_NUM_1, rx, sizeof(rx), pdMS_TO_TICKS(300));
    return n > 0 && is_version_reply(rx, n);
}

/** Log what the radio prints at the ROM's 115200 baud: shows a radio that keeps (re)booting. */
static void log_rcp_boot_output()
{
    uart_set_baudrate(UART_NUM_1, 115200);
    uart_flush_input(UART_NUM_1);
    char rx[160];
    int n = uart_read_bytes(UART_NUM_1, rx, sizeof(rx) - 1, pdMS_TO_TICKS(1500));
    uart_set_baudrate(UART_NUM_1, MESP_RCP_BAUD);
    if (n <= 0) {
        ESP_LOGW(TAG, "The radio sends nothing (not wired, or not running the radio firmware?)");
        return;
    }
    int zeros = 0;
    for (int i = 0; i < n; i++) zeros += rx[i] == 0;
    if (zeros * 2 > n) {
        // An idle UART line is high; an unpowered chip (only fed through its RX pin) pulls it low,
        // which reads as mostly 0x00 bytes.
        ESP_LOGW(TAG, "The radio's TX line is held low – it is probably not powered (check its 5V and GND)");
        return;
    }
    ESP_LOGW(TAG, "The radio sends %d bytes, %d of them 0x00", n, zeros);
    for (int i = 0; i < n; i++) {
        if (rx[i] < 0x20 || rx[i] > 0x7e) rx[i] = '.';
    }
    rx[n] = '\0';
    ESP_LOGW(TAG, "The radio sends at 115200 baud: %s", rx);
    if (strstr(rx, "rst:") || strstr(rx, "ESP-ROM")) {
        ESP_LOGW(TAG, "The radio keeps restarting – its power supply is probably too weak");
    }
}

static void wait_for_rcp()
{
    uart_config_t cfg = {};
    cfg.baud_rate = MESP_RCP_BAUD;
    cfg.data_bits = UART_DATA_8_BITS;
    cfg.parity = UART_PARITY_DISABLE;
    cfg.stop_bits = UART_STOP_BITS_1;
    cfg.flow_ctrl = UART_HW_FLOWCTRL_DISABLE;
    cfg.source_clk = UART_SCLK_DEFAULT;
    ESP_ERROR_CHECK(uart_driver_install(UART_NUM_1, 256, 0, 0, nullptr, 0));
    ESP_ERROR_CHECK(uart_param_config(UART_NUM_1, &cfg));
    ESP_ERROR_CHECK(uart_set_pin(UART_NUM_1, MESP_RCP_HOST_TX_PIN, MESP_RCP_HOST_RX_PIN, UART_PIN_NO_CHANGE,
                                 UART_PIN_NO_CHANGE));

    // OpenThread reboots the chip if the radio does not answer, so only start it once it does.
    for (int attempt = 0; !rcp_answers(); attempt++) {
        if (attempt % 30 == 0) {
            ESP_LOGE(TAG,
                     "Thread radio is not responding (host RX GPIO%d, TX GPIO%d, %d baud). Check that it is "
                     "powered, shares GND, is wired TX->RX / RX->TX and runs the vibes-espmatter radio firmware. "
                     "Waiting...",
                     MESP_RCP_HOST_RX_PIN, MESP_RCP_HOST_TX_PIN, MESP_RCP_BAUD);
            log_rcp_boot_output();
        }
        vTaskDelay(pdMS_TO_TICKS(700));
    }
    ESP_LOGI(TAG, "Thread radio answered");
    // OpenThread installs its own driver on this port.
    uart_driver_delete(UART_NUM_1);
}

/** Needs both a running OpenThread stack and the Wi-Fi backbone; whichever comes last starts it. */
static void try_start_border_router()
{
    if (!mesp_thread_ready() || !s_ip_ready.load() || s_br_started.exchange(true)) {
        return;
    }
    OtLock lock;
    esp_openthread_set_backbone_netif(esp_netif_get_handle_from_ifkey("WIFI_STA_DEF"));
    esp_err_t err = esp_openthread_border_router_init();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Border router init failed: %s", esp_err_to_name(err));
    } else {
        ESP_LOGI(TAG, "Border router started");
    }
}

void mesp_thread_on_ip()
{
    s_ip_ready = true;
    try_start_border_router();
}

static otError form_network_locked(otInstance *instance)
{
    otOperationalDataset dataset;
    memset(&dataset, 0, sizeof(dataset));
    otError err = otDatasetCreateNewNetwork(instance, &dataset);
    if (err != OT_ERROR_NONE) {
        return err;
    }
    if (strlen(MESP_THREAD_NETWORK_NAME) > 0) {
        otNetworkNameFromString(&dataset.mNetworkName, MESP_THREAD_NETWORK_NAME);
        dataset.mComponents.mIsNetworkNamePresent = true;
    }
#if MESP_THREAD_CHANNEL > 0
    dataset.mChannel = MESP_THREAD_CHANNEL;
    dataset.mComponents.mIsChannelPresent = true;
#endif
    return otDatasetSetActive(instance, &dataset);
}

static void start_thread_locked(otInstance *instance)
{
    if (!otIp6IsEnabled(instance)) {
        otIp6SetEnabled(instance, true);
    }
    if (otThreadGetDeviceRole(instance) == OT_DEVICE_ROLE_DISABLED) {
        otThreadSetEnabled(instance, true);
    }
}

// Calls that wait for a radio response (forming a network, enabling Thread) must run in the
// OpenThread task: from another task they race its UART select() and corrupt the heap.
static void auto_start_in_ot_task(void *)
{
    otInstance *instance = esp_openthread_get_instance();
    if (!otDatasetIsCommissioned(instance)) {
#if MESP_THREAD_AUTO_FORM
        ESP_LOGI(TAG, "No Thread dataset found, forming a new network '%s'", MESP_THREAD_NETWORK_NAME);
        otError err = form_network_locked(instance);
        if (err != OT_ERROR_NONE) {
            ESP_LOGE(TAG, "Failed to form network: %s", otThreadErrorToString(err));
        }
#else
        ESP_LOGW(TAG, "No Thread dataset – form a network from the web interface");
        return;
#endif
    }
    start_thread_locked(instance);
    ESP_LOGI(TAG, "Thread started");
}

static void ot_mainloop_task(void *)
{
    esp_openthread_launch_mainloop();
    ESP_LOGE(TAG, "OpenThread main loop exited");
    vTaskDelete(nullptr);
}

static void thread_init_task(void *)
{
    wait_for_rcp();
    s_radio = RADIO_STARTING;

    // Eventfds used by OpenThread: netif, task queue, radio driver.
    esp_vfs_eventfd_config_t eventfd_config = {.max_fds = 3};
    esp_err_t err = esp_vfs_eventfd_register(&eventfd_config);
    if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
        ESP_LOGE(TAG, "eventfd register failed: %s", esp_err_to_name(err));
        vTaskDelete(nullptr);
    }

    /* OpenThread talks Spinel to the external radio (RCP) over UART1. */
    esp_openthread_platform_config_t config = {};
    config.radio_config.radio_mode = RADIO_MODE_UART_RCP;
    config.radio_config.radio_uart_config.port = UART_NUM_1;
    config.radio_config.radio_uart_config.uart_config.baud_rate = MESP_RCP_BAUD;
    config.radio_config.radio_uart_config.uart_config.data_bits = UART_DATA_8_BITS;
    config.radio_config.radio_uart_config.uart_config.parity = UART_PARITY_DISABLE;
    config.radio_config.radio_uart_config.uart_config.stop_bits = UART_STOP_BITS_1;
    config.radio_config.radio_uart_config.uart_config.flow_ctrl = UART_HW_FLOWCTRL_DISABLE;
    config.radio_config.radio_uart_config.uart_config.source_clk = UART_SCLK_DEFAULT;
    config.radio_config.radio_uart_config.rx_pin = (gpio_num_t)MESP_RCP_HOST_RX_PIN;
    config.radio_config.radio_uart_config.tx_pin = (gpio_num_t)MESP_RCP_HOST_TX_PIN;
    config.host_config.host_connection_mode = HOST_CONNECTION_MODE_NONE;
    config.port_config.storage_partition_name = "nvs";
    config.port_config.netif_queue_size = 10;
    config.port_config.task_queue_size = 10;
    ESP_ERROR_CHECK(esp_openthread_init(&config));

    esp_netif_config_t netif_config = ESP_NETIF_DEFAULT_OPENTHREAD();
    esp_netif_t *netif = esp_netif_new(&netif_config);
    ESP_ERROR_CHECK(esp_netif_attach(netif, esp_openthread_netif_glue_init(&config)));

    xTaskCreate(ot_mainloop_task, "ot_main", 8192, nullptr, 5, nullptr);
    s_radio = RADIO_READY;
    ESP_LOGI(TAG, "OpenThread running");

    try_start_border_router();
    esp_openthread_task_queue_post(auto_start_in_ot_task, nullptr);
    vTaskDelete(nullptr);
}

void mesp_thread_start()
{
    // esp_openthread_init() logs while it sets up the stack and the radio: 6144 bytes overflowed into
    // the neighbouring heap block (crash in the next malloc, "Dbus write to cache rejected").
    xTaskCreate(thread_init_task, "mesp_thread", 12288, nullptr, 5, nullptr);
}

bool mesp_thread_get_active_dataset(uint8_t *buf, uint8_t *len)
{
    if (!mesp_thread_ready()) return false;
    OtLock lock;
    otOperationalDatasetTlvs tlvs;
    if (otDatasetGetActiveTlvs(esp_openthread_get_instance(), &tlvs) != OT_ERROR_NONE) {
        return false;
    }
    memcpy(buf, tlvs.mTlvs, tlvs.mLength);
    *len = tlvs.mLength;
    return true;
}

const char *mesp_thread_radio()
{
    static const char *const names[] = {"waiting", "starting", "ready"};
    return names[s_radio.load()];
}

esp_err_t mesp_thread_form_network()
{
    if (!mesp_thread_ready()) return ESP_ERR_INVALID_STATE;
    // Runs in the OpenThread task (see auto_start_in_ot_task).
    return esp_openthread_task_queue_post(
        [](void *) {
            otInstance *instance = esp_openthread_get_instance();
            otThreadSetEnabled(instance, false);
            otError err = form_network_locked(instance);
            if (err != OT_ERROR_NONE) {
                ESP_LOGE(TAG, "Failed to form network: %s", otThreadErrorToString(err));
                return;
            }
            start_thread_locked(instance);
            ESP_LOGI(TAG, "Formed a new Thread network");
        },
        nullptr);
}
